package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

func primeFactorization(n int64) [][2]int64 {
	res := make([][2]int64, 0)
	var d int64 = 2
	for d*d <= n {
		if n%d == 0 {
			cnt := int64(0)
			for n%d == 0 {
				n /= d
				cnt++
			}
			res = append(res, [2]int64{d, cnt})
		}
		d++
	}
	if n > 1 {
		res = append(res, [2]int64{n, 1})
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)

	d := primeFactorization(n)
	if len(d) == 1 {
		fmt.Println(d[0][0])
	} else {
		fmt.Println(1)
	}
	_ = math.Max // to avoid unused import if math is not needed
}

